selected.compute:
options = read('/input/options')
result = read('/output/selection')
if not valid(result):
    result = []
    for group in combinations(options, 3):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        write('/output/selection', result)
if receipt('report') == 'success':
    pass
elif receipt('report') == 'unknown':
    status('report')
    if receipt('report') != 'success':
        pass
else:
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
